const staticData = $getWorkflowStaticData('global');
if (!staticData.seen) staticData.seen = {};
const body = $json.body || $json;
const deliveryId = String(body.delivery_id || body.event_id || body.lead_id || '');
if (!deliveryId) {
  return [];
}
if (staticData.seen[deliveryId]) {
  return [];
}
staticData.seen[deliveryId] = Date.now();
const lead = body.lead || {};
const time = new Date(body.occurred_at || Date.now()).toLocaleString('es-CO', { timeZone: body.timezone || 'America/Bogota' });
const adminUrl = body.admin_url || 'https://peskids.op-sly.com/admin';
return [{
  json: {
    delivery_id: deliveryId,
    discord_message: {
      embeds: [{
        title: `🔥 Nuevo interesado Peskids: ${lead.parent_name || 'Sin nombre'}`,
        color: 16711680,
        fields: [
          { name: '📧 Email', value: lead.email || 'N/A', inline: true },
          { name: '📞 Teléfono', value: lead.phone || 'N/A', inline: true },
          { name: '📍 Modalidad', value: lead.class_modality || 'N/A', inline: true },
          { name: '🏘️ Barrio', value: lead.neighborhood || 'N/A', inline: true },
          { name: '📚 Grado', value: lead.grade_interested || 'N/A', inline: true },
          { name: '🔗 Fuente', value: lead.referral_source || 'web', inline: true },
          { name: '🔗 Admin', value: adminUrl, inline: false }
        ],
        footer: { text: `⏰ ${time}` }
      }]
    }
  }
}];
